/**
 * Gateway WebSocket client
 *
 * One connection per agent conversation, created lazily on first send
 * and owned by the surface that created it — later conversation modes
 * hold their own socket the same way.
 *
 * Wire shapes come from the shared contract generated by `just
 * typegen` (gateway/wstypes → wstypes.gen).
 */

import type { Event } from '#lib/types/gen/wstypes.gen'

/** Events the gateway sends to the client. */
export type AgentSocketEvent = Event

export function createAgentSocket(onEvent: (event: AgentSocketEvent) => void) {
	let socket: WebSocket | undefined
	const pending: { type: string }[] = []

	function connect() {
		// Same-origin /ws like the api client's /api: proxied by the vite
		// dev/preview servers; prod serves it from the single binary.
		socket = new WebSocket('/ws')
		socket.onopen = () => {
			for (const msg of pending.splice(0)) {
				send(msg)
			}
		}
		socket.onmessage = (message) => {
			try {
				onEvent(JSON.parse(message.data) as AgentSocketEvent)
			} catch {
				console.warn('agent socket: unparseable frame', message.data)
			}
		}
		socket.onclose = () => {
			socket = undefined
		}
	}

	function send(msg: { type: string }) {
		if (!socket || socket.readyState !== WebSocket.OPEN) {
			pending.push(msg)
			return
		}
		socket.send(JSON.stringify(msg))
	}

	return {
		/** Send the prompt tag over the connection; the payload lands
		 * with the prompt boundary commit. */
		sendPrompt() {
			if (!socket) {
				connect()
			}
			send({ type: 'prompt' })
		},

		close() {
			pending.length = 0
			socket?.close()
			socket = undefined
		}
	}
}
